package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;
import org.apache.commons.math3.linear.*;

/** Fixed pooled PLS score extraction followed by structural Gaussian mixture estimation. */
public final class PlsMixture {
    private PlsMixture(){}
    public record SegmentEffects(int segment,double[][] paths,double[][] centeredStandardizedPaths,double[][] referenceScaledPaths,double[][] totalEffects,double[][] referenceTotalEffects,double[][] differencesFromPooled){
        public SegmentEffects{paths=Matrices.copy(paths);centeredStandardizedPaths=Matrices.copy(centeredStandardizedPaths);referenceScaledPaths=Matrices.copy(referenceScaledPaths);totalEffects=Matrices.copy(totalEffects);referenceTotalEffects=Matrices.copy(referenceTotalEffects);differencesFromPooled=Matrices.copy(differencesFromPooled);}@Override public double[][] paths(){return Matrices.copy(paths);}@Override public double[][] centeredStandardizedPaths(){return Matrices.copy(centeredStandardizedPaths);}@Override public double[][] referenceScaledPaths(){return Matrices.copy(referenceScaledPaths);}@Override public double[][] totalEffects(){return Matrices.copy(totalEffects);}@Override public double[][] referenceTotalEffects(){return Matrices.copy(referenceTotalEffects);}@Override public double[][] differencesFromPooled(){return Matrices.copy(differencesFromPooled);}
    }
    public record Result(PlsSem.Options modelOptions,boolean originalUnits,PlsSem.Fit pooledModel,double[][] scoreObservations,double[][] pooledScorePaths,FiniteMixture.Result mixture,List<SegmentEffects> segmentEffects,List<String> warnings){public Result{scoreObservations=Matrices.copy(scoreObservations);pooledScorePaths=Matrices.copy(pooledScorePaths);segmentEffects=List.copyOf(segmentEffects);warnings=List.copyOf(warnings);}@Override public double[][] scoreObservations(){return Matrices.copy(scoreObservations);}@Override public double[][] pooledScorePaths(){return Matrices.copy(pooledScorePaths);}}
    public static Result fit(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options modelOptions,FiniteMixture.Options options,boolean originalUnits,IntConsumer progress){
        if(blocks.size()>200||(long)blocks.size()*blocks.size()*options.segments()>2000000L)throw new IllegalArgumentException("PLS mixture effect matrices exceed the current size limit.");var pooled=PlsSem.fit(data,blocks,edges,modelOptions);if(!pooled.converged())throw new IllegalArgumentException("FIMIX requires a converged pooled PLS solution.");double[][] scores=pooled.scores();if(originalUnits){double[][] weights=pooled.weights();double[] sd=new double[data[0].length];for(int construct=0;construct<blocks.size();construct++){Matrices.interrupted();int[] columns=blocks.get(construct).columns();double[] normalized=new double[columns.length];double sum=0;for(int j=0;j<columns.length;j++){int column=columns[j];if(sd[column]==0){double mean=0;for(int i=0;i<data.length;i++)mean+=(data[i][column]-mean)/(i+1);double variance=0;for(double[] row:data)variance+=Math.pow(row[column]-mean,2)/data.length;sd[column]=Math.sqrt(variance);}normalized[j]=weights[construct][j]/sd[column];sum+=normalized[j];}if(sum==0||!Double.isFinite(sum))throw new IllegalArgumentException("Unstandardized composite weights cannot be normalized.");for(int j=0;j<columns.length;j++)normalized[j]/=sum;for(int row=0;row<data.length;row++){scores[row][construct]=0;for(int j=0;j<columns.length;j++)scores[row][construct]+=normalized[j]*data[row][columns[j]];}}}
        List<String> names=blocks.stream().map(PlsSem.Block::name).toList();var mixture=FiniteMixture.fit(scores,names,edges,options,progress);int count=blocks.size();double[][] pooledPaths=new double[count][count];for(int target=0;target<count;target++){int response=target;int[] parents=edges.stream().filter(edge->edge.target()==response).mapToInt(PlsSem.Edge::source).toArray();if(parents.length==0)continue;int offset=options.intercept()?1:0;double[][] x=new double[scores.length][parents.length+offset];double[] y=new double[scores.length];for(int row=0;row<scores.length;row++){if(offset==1)x[row][0]=1;for(int j=0;j<parents.length;j++)x[row][j+offset]=scores[row][parents[j]];y[row]=scores[row][target];}double[] coefficients=new QRDecomposition(new Array2DRowRealMatrix(x,false),1e-12).getSolver().solve(new ArrayRealVector(y,false)).toArray();for(int j=0;j<parents.length;j++)pooledPaths[parents[j]][target]=coefficients[j+offset];}
        List<SegmentEffects> effects=new ArrayList<>();double[][] posterior=mixture.probabilities();for(var segment:mixture.segments()){Matrices.interrupted();int index=segment.index();double mass=0;double[] means=new double[count],variance=new double[count],second=new double[count];for(int row=0;row<scores.length;row++){double weight=posterior[row][index];mass+=weight;for(int column=0;column<count;column++)means[column]+=weight*scores[row][column];}for(int column=0;column<count;column++)means[column]/=mass;for(int row=0;row<scores.length;row++)for(int column=0;column<count;column++){double weight=posterior[row][index];variance[column]+=weight*Math.pow(scores[row][column]-means[column],2);second[column]+=weight*scores[row][column]*scores[row][column];}double[][] paths=new double[count][count],standardized=new double[count][count],reference=new double[count][count],differences=new double[count][count];for(var equation:segment.equations()){int target=equation.response();int[] parents=equation.parents();double[] beta=equation.coefficients();for(int j=0;j<parents.length;j++){int source=parents[j];paths[source][target]=beta[j];standardized[source][target]=variance[target]>0?beta[j]*Math.sqrt(variance[source]/variance[target]):Double.NaN;reference[source][target]=second[target]>0?beta[j]*Math.sqrt(second[source]/second[target]):Double.NaN;differences[source][target]=(originalUnits?beta[j]:reference[source][target])-pooledPaths[source][target];}}effects.add(new SegmentEffects(index,paths,standardized,reference,totals(paths,edges),totals(reference,edges),differences));}
        List<String> warnings=new ArrayList<>(mixture.warnings());warnings.add("The pooled PLS model is estimated once; FIMIX conditions on its fixed "+(originalUnits?"unstandardized normalized-weight":"standardized")+" score observations. Mixture regression coefficients are not hard-segment PLS refits.");warnings.add("Centered within-segment standardized paths use posterior-centered variances. Reference-scaled paths use posterior-weighted uncentered second moments, matching the recovered standardized-score report. Raw and reference-scaled total effects are separate. Pooled differences follow the selected input-score/report metric.");return new Result(modelOptions,originalUnits,pooled,scores,pooledPaths,mixture,effects,warnings);
    }
    private static double[][] totals(double[][] paths,List<PlsSem.Edge> edges){int p=paths.length;double[][] result=new double[p][p];int[] degrees=new int[p];List<List<Integer>> children=new ArrayList<>();for(int node=0;node<p;node++)children.add(new ArrayList<>());for(var edge:edges){degrees[edge.target()]++;children.get(edge.source()).add(edge.target());}List<Integer> order=new ArrayList<>();for(int node=0;node<p;node++)if(degrees[node]==0)order.add(node);for(int j=0;j<order.size();j++)for(int child:children.get(order.get(j)))if(--degrees[child]==0)order.add(child);for(int source=0;source<p;source++)result[source][source]=1;for(int parent:order)for(int child:children.get(parent))for(int source=0;source<p;source++)result[source][child]+=result[source][parent]*paths[parent][child];for(int source=0;source<p;source++)result[source][source]=0;return result;}
}
